(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.035-t*0.15)*8+Math.cos(y*0.04+t*0.4)*6;
  const w2y = Math.cos(y*0.03+t*0.2)*8+Math.sin(x*0.025-t*0.45)*6;
  const w3x = Math.sin((x+y)*0.01+t*0.18)*12;
  const w3y = Math.cos((x-y)*0.012-t*0.22)*12;
  const sx = x+w1x+w2x+w3x, sy = y+w1y+w2y+w3y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 2],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.5],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 3],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+2)*65, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+1)*95, 200+Math.sin(t*0.75)*75, 0.065, 2.4, 2.5],
    [200+Math.sin(t*0.38+6)*85, 220+Math.cos(t*0.48)*55, 0.095, 1.8, 1.2]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp+ph);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    cS += Math.cos(d*f*0.5-t*sp*0.3+ph*2);
  }
  const n = src.length;
  const act=aS/n, inh=iS/n, cor=cS/n;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.07+t*1.5)*Math.cos(sy*0.06-t*1.2)*0.3;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.08-ang*2+t*0.8)*0.3;
  const spiral = (sp1+sp2)*0.4+sp3;
  const vx = Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const vy = Math.sin((sx+sy)*0.1+t)*0.5;
  const cell = Math.tanh((vx+vy)*1.5)*0.3;
  const voronoi = () => {
    let md = 99, md2 = 99;
    for (let i = 0; i < 7; i++) {
      const px = 80+i*60+Math.sin(t*0.3+i*1.7)*25;
      const py = 40+Math.sin(i*2.3+t*0.25)*80+Math.cos(i*1.1+t*0.35)*40;
      const d = Math.sqrt((sx-px)**2+(sy-py)**2);
      if (d < md) { md2 = md; md = d; } else if (d < md2) { md2 = d; }
    }
    return Math.sin((md2-md)*0.3)*0.25;
  };
  const vor = voronoi();
  const feed = act*0.55 - inh*0.35 + bg*0.2 + spiral*0.3 + cor*0.15 + cell*0.15 + vor*0.1;
  const reaction = Math.tanh(feed*2.2);
  const lap = (px,py) => {
    let s = 0;
    for (let dx=-1;dx<=1;dx++) for(let dy=-1;dy<=1;dy++) {
      const nx=px+dx*4, ny=py+dy*4;
      const lv = Math.sin(nx*0.04+ny*0.025+t*0.8)+Math.sin(nx*0.03-ny*0.04+t*1.1);
      s += lv;
    }
    return s/9;
  };
  const lapV = lap(sx,sy);
  const micro = Math.sin((lapV-bg1)*5)*0.15;
  const blend = reaction*0.6 + cell*0.15 + vor*0.1 + micro*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,85],[15,90,120],[18,135,130],
    [45,170,145],[130,195,120],[210,200,80],[230,160,60],
    [215,110,70],[185,65,80],[130,35,75],[65,18,60],[5,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const r1 = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g1 = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b1 = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow = Math.max(0, Math.abs(reaction)-0.5)*0.4;
  const shimmer = Math.sin(sx*0.3+sy*0.2+t*3)*0.05+0.95;
  const cm = 1+cor*0.08;
  return [
    Math.min(255, ((r1*lum*edge+glow*255*0.3)*cm*shimmer))|0,
    Math.min(255, ((g1*lum*edge+glow*200*0.2)*shimmer))|0,
    Math.min(255, ((b1*lum*edge+glow*150*0.15)*cm*1.05*shimmer))|0
  ];
}
